function sr_class(string $class):string{return "contains(concat(' ',normalize-space(@class),' '),' $class ')";}
function sr_html(DOMNode $node,string $html):void{$tmp=new DOMDocument();libxml_use_internal_errors(true);$tmp->loadHTML('<?xml encoding="UTF-8"><div id="fragment">'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);libxml_clear_errors();$fragment=(new DOMXPath($tmp))->query('//*[@id="fragment"]')->item(0);foreach(iterator_to_array($fragment->childNodes)as $child)$node->appendChild($node->ownerDocument->importNode($child,true));}
function sr_set(DOMNode $root,string $class,string $text):void{foreach(sr_query('.//*['.sr_class($class).']',$root)as $node){sr_text($node,$text);$node->removeAttribute('data-i18n');}}
function sr_original(string $key):string{
 global $cfg,$lang,$brand,$sourceDictionary,$sourceBindings,$sourceRows,$draft;
 if($key==='brand.name')return $brand;
 if($key==='offers.lead'&&!$draft&&!public_offers_state()['has_offers'])return '';
 if($key==='brand.slogan'){ $text=setting_text('public_slogan');return !$draft&&!public_offers_state()['has_offers']&&public_offers_references($text)?'':$text;}
 if($key==='footer.copy')return public_copyright($lang,$brand);
 if($key==='contact.phone')return (string)$cfg['public_phone'];
 if($key==='contact.email')return (string)$cfg['public_email'];
 if($key==='contact.hours')return setting_text('public_hours');
 if(isset($sourceBindings[$key])){$binding=$sourceBindings[$key];foreach($sourceRows[$binding['type']]as $row)if($row['template_key']===$binding['template_key'])return pv(public_content_for_display(decode($row['content_json'])),$binding['field']);return '';}
 return str_replace('{{company}}',$brand,$sourceDictionary[$lang][$key]??$sourceDictionary['en'][$key]??'');
}
